-- Pre-feature SQLite schema and fictional data generated by base 88f6d9b.
-- sqlite3's dump lists some rows before their parent tables; validate after loading.
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE books(id TEXT PRIMARY KEY,title TEXT NOT NULL,author TEXT NOT NULL,deleted_at INTEGER);
INSERT INTO "books" VALUES('d47901b3-207d-4027-9719-180578ccd8c8','Pre-feature fictional fixture','',NULL);
CREATE TABLE chapter_version_labels(version_id TEXT PRIMARY KEY REFERENCES chapter_versions(id) ON DELETE CASCADE,label TEXT,label_revision INTEGER NOT NULL CHECK(label_revision BETWEEN 1 AND 9007199254740991),updated_at INTEGER NOT NULL);
CREATE TABLE chapter_versions(id TEXT PRIMARY KEY,chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,revision INTEGER NOT NULL,body TEXT NOT NULL,source TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(chapter_id,revision));
CREATE TABLE chapters(id TEXT PRIMARY KEY,volume_id TEXT NOT NULL REFERENCES volumes(id),title TEXT NOT NULL,body TEXT NOT NULL,revision INTEGER NOT NULL,sort_order INTEGER NOT NULL, deleted_at INTEGER);
INSERT INTO "chapters" VALUES('2f05e9a9-ea1e-43ee-b483-53fac44277ab','43c6a770-293f-4ead-832a-ae41d021673f','初章','',0,0,NULL);
CREATE TABLE context_task_items(task_id TEXT NOT NULL REFERENCES context_tasks(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,record TEXT NOT NULL,PRIMARY KEY(task_id,ordinal));
CREATE TABLE context_task_plan(task_id TEXT NOT NULL REFERENCES context_tasks(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,record TEXT NOT NULL,PRIMARY KEY(task_id,ordinal));
CREATE TABLE context_tasks(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN ('queued','running','completed','cancelled','failed','interrupted')),record TEXT NOT NULL,manifest TEXT NOT NULL,input_epoch TEXT NOT NULL,request_key TEXT NOT NULL UNIQUE,request_payload TEXT NOT NULL,created_at INTEGER NOT NULL,storage_bytes INTEGER NOT NULL);
CREATE TABLE edit_proposals(id TEXT PRIMARY KEY,client_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,payload TEXT NOT NULL,chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,base_revision INTEGER NOT NULL,old_body TEXT NOT NULL,new_body TEXT NOT NULL,reason TEXT NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','accepted','rejected','cancelled')),created_at INTEGER NOT NULL,UNIQUE(client_id,idempotency_key));
CREATE TABLE material_content_versions(id TEXT PRIMARY KEY,material_id TEXT NOT NULL REFERENCES materials(id) ON DELETE CASCADE,material_revision INTEGER NOT NULL,title TEXT NOT NULL,fields TEXT NOT NULL,created_at INTEGER NOT NULL,source TEXT NOT NULL,byte_count INTEGER NOT NULL,UNIQUE(material_id,material_revision));
CREATE TABLE material_proposal_audit(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES material_proposals(id) ON DELETE CASCADE,material_id TEXT NOT NULL,action TEXT NOT NULL,actor TEXT NOT NULL,revision INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE material_proposals(id TEXT PRIMARY KEY,client_id TEXT NOT NULL,material_id TEXT NOT NULL REFERENCES materials(id) ON DELETE CASCADE,base_revision INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','accepted','rejected','cancelled')),record TEXT NOT NULL,payload TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(client_id,idempotency_key));
CREATE TABLE materials(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,kind TEXT NOT NULL,title TEXT NOT NULL,fields TEXT NOT NULL,volume_id TEXT REFERENCES volumes(id) ON DELETE SET NULL,chapter_id TEXT REFERENCES chapters(id) ON DELETE SET NULL,revision INTEGER NOT NULL,deleted_at INTEGER,updated_at INTEGER NOT NULL,field_bytes INTEGER NOT NULL,source_chapter_id TEXT,source_revision INTEGER,story_order INTEGER NOT NULL DEFAULT 0,story_time TEXT,tracking_status TEXT,payoff_chapter_id TEXT,payoff_revision INTEGER, content_review_required INTEGER NOT NULL DEFAULT 0 CHECK(content_review_required IN (0,1)));
CREATE TABLE volumes(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id),title TEXT NOT NULL,sort_order INTEGER NOT NULL, deleted_at INTEGER);
INSERT INTO "volumes" VALUES('43c6a770-293f-4ead-832a-ae41d021673f','d47901b3-207d-4027-9719-180578ccd8c8','启程',0,NULL);
CREATE TABLE workflow_audit(id TEXT PRIMARY KEY,chapter_id TEXT REFERENCES chapters(id) ON DELETE CASCADE,action TEXT NOT NULL,source TEXT NOT NULL,revision INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE workflow_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO "workflow_meta" VALUES('epoch','ea8b8497-93c2-4aee-9914-f5e53f971baa');
CREATE TABLE writing_packs(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,chapter_id TEXT NOT NULL,payload TEXT NOT NULL,byte_count INTEGER NOT NULL,manifest TEXT NOT NULL,originating_epoch TEXT NOT NULL);
CREATE TABLE writing_policies(chapter_id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,revision INTEGER NOT NULL,mode TEXT NOT NULL,record TEXT NOT NULL);
CREATE TABLE writing_proposals(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE,chapter_id TEXT NOT NULL,pack_id TEXT NOT NULL REFERENCES writing_packs(id),client_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,decision TEXT NOT NULL,live_epoch TEXT,payload TEXT NOT NULL,byte_count INTEGER NOT NULL,created_at INTEGER NOT NULL,UNIQUE(client_id,idempotency_key));
CREATE INDEX proposal_chapter ON edit_proposals(chapter_id);
CREATE INDEX chapter_version_metadata ON chapter_versions(chapter_id,revision DESC,id DESC,source,created_at);
CREATE INDEX materials_book_id ON materials(book_id,id);
CREATE INDEX material_proposals_card ON material_proposals(material_id);
CREATE INDEX context_tasks_status ON context_tasks(status,created_at);
CREATE INDEX writing_pack_chapter ON writing_packs(chapter_id,id);
CREATE INDEX writing_proposal_chapter ON writing_proposals(chapter_id,id);
COMMIT;
PRAGMA foreign_keys=ON;
